pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 warpTime, uint256 blockNum) public {
        vm.assume(amount <= 1000000 ether);
        vm.assume(warpTime > 0);
        vm.assume(blockNum <= 1000000000);

        // Setup adversary that always reverts on receiving ether
        Reverter reverter = new Reverter();

        // Initialize pastBlockTime so that block.timestamp > pastBlockTime holds
        vm.warp(1);
        vm.roll(1);
        vm.deal(address(c), 0);

        // Set pastBlockTime to 0 by sending a legitimate 10 ether call that does not transfer out
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "setup call failed");

        // Warp to the fuzzed timestamp and roll to fuzzed block number
        vm.warp(warpTime);
        vm.roll(blockNum);

        uint256 balanceBefore = address(c).balance;

        // Ensure the caller has enough ether
        address caller = address(0x12345);
        vm.deal(caller, amount);
        vm.prank(caller);

        // The adversarial party is reverter - if the fallback tries to transfer ether to msg.sender,
        // but the reference only transfers when amount == 10 ether and blockNum%15==0.
        // We make msg.sender the reverter contract so that any transfer attempt fails.
        // This lets us observe state changes without ether leaving.
        (bool success,) = address(c).call{value: amount}("");

        uint256 balanceAfter = address(c).balance;

        // Reference invariant: the contract's ether balance must equal balanceBefore + amount
        // because the only way ether leaves is via transfer(msg.sender).
        // The reference reverts when amount != 10 ether, so balanceAfter == balanceBefore.
        // The buggy version accepts any amount, updates state, and attempts transfer (which may fail due to reverter).
        // Thus buggy version can have balanceAfter == balanceBefore + amount != balanceBefore when amount != 10 ether.
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

