pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 number, uint256 timestamp, uint256 msgValue) public {
        // Restrict to admissible domain: msg.value must be exactly 10 ether
        vm.assume(msgValue == 10 ether);
        // Block timestamp must be > pastBlockTime (0 initially)
        vm.assume(timestamp > 0);
        // Warp and roll
        vm.warp(timestamp);
        vm.roll(number);
        // Fund an EOA and call fallback
        address caller = address(0x1234);
        vm.deal(caller, 100 ether);
        vm.prank(caller);
        try c.fallback{value: msgValue}() {
            // fallback succeeded
        } catch {
            // fallback reverted
        }
        // After execution, if selfdestruct occurred (block.number % 15 == 0),
        // the contract is destroyed and its code is empty, but balance must be 0.
        // For the reference contract, ether stays in the contract (unless block.number % 15 == 0 in which case it sends balance to caller).
        // The universal property: The reference contract's balance after fallback is never zero for a caller that sent 10 ether
        // unless the caller receives the whole balance. The buggy version selfdestructs sending balance to address(0),
        // making address(c).balance zero while balance should be non-zero (since address(0) is not the caller).
        if (number % 15 == 0) {
            // In the reference, the balance should be 0 because it transferred everything to the caller.
            assertTrue(address(c).balance == 0);
        } else {
            // In the reference, the balance should be exactly the ether received so far.
            // In the buggy version, selfdestruct only triggers on number % 15 == 0, so this case is identical -> no difference detected.
            // We need a property that always holds for reference but is broken by buggy.
            // Since selfdestruct destroys the contract, subsequent calls will fail.
            // Property: after a successful fallback, the contract's code size is non-zero (reference is alive, buggy is dead after selfdestruct).
            // But selfdestruct only happens on number % 15 == 0.
            // Let's check: For any call, if block.number % 15 == 0, the contract's balance after call must equal 0 (reference sends to caller, buggy sends to address(0)).
            // But the rule should hold for all inputs. Let's state: address(c).balance after call equals either 0 (if number % 15 == 0) or the cumulative sent ether otherwise.
            // But the buggy version also yields 0 balance after selfdestruct (destroyed), so the balance check alone doesn't distinguish.
            // The real difference: In reference, caller receives balance; in buggy, address(0) receives balance, so the caller's balance doesn't increase.
            // We can assert that the caller's balance after call, minus before call, is >= address(c).balance before call if number % 15 == 0.
            // Since the fuzzer can control number, timestamp, and msgValue, we can check the caller's balance change.
            uint256 callerBalanceBefore = caller.balance;
            vm.prank(caller);
            try c.fallback{value: msgValue}() {} catch {}
            uint256 callerBalanceAfter = caller.balance;
            // If selfdestruct didn't occur, reference and buggy both just increase contract balance.
            // If selfdestruct occurred, reference sends entire balance to caller, buggy sends to address(0).
            // So for number % 15 == 0, reference: callerBalanceAfter - callerBalanceBefore == address(c).balance (before call) + msgValue? Wait, selfdestruct sends the contract's balance to the designated address.
            // In reference, transfer sends all balance to caller. So caller gets address(c).balance (including the just-sent 10 ether).
            // In buggy, selfdestruct(address(0)) sends all balance to address(0), so caller only loses the sent value.
            // Property: after a call with block.number % 15 == 0, the caller's ether balance must increase by the contract's balance before the call.
            // But we only have one call in this test, so we can check the difference.
            // Let's restructure: do one call and check the property.
        }
    }
}

