pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 msgValue, uint256 blockNum, uint256 blockTime) public {
        // 1. Admissible domain: require msg.value == 10 ether and block.timestamp > pastBlockTime.
        //    Initially pastBlockTime is 0, so blockTime > 0 is enough for first call.
        //    The fuzzer must supply 10 ether, but we can bind blockTime to a reasonable range.
        vm.assume(msgValue == 10 ether);
        vm.assume(blockTime > 0);
        // 2. Setup: fund a caller, warp to blockTime, set block number.
        address caller = address(0x1234);
        vm.deal(caller, msgValue);
        vm.warp(blockTime);
        vm.roll(blockNum);
        // 3. Drive the contract through fallback.
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: msgValue}("");
        // 4. Universal property: If the fallback did not revert, the reference contract remains alive.
        //    The buggy version self-destructs when (block.number % 15 == 0), making its code size zero.
        assertTrue(!ok || address(c).code.length > 0);
    }
}

