pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blocknum, uint256 blkTs) public {
        // Admissible domain: blockTimestamp must be strictly increasing across calls
        vm.assume(blkTs > 0);
        vm.assume(blocknum > 0);
        // Avoid block.number multiple of 15 so no transfer occurs in the call
        vm.assume(blocknum % 15 != 0);

        // Setup first call to set pastBlockTime
        vm.warp(1);
        vm.roll(1);
        vm.deal(address(this), 10 ether);
        c.fallback{value: 10 ether}();

        // Fuzzed second call
        vm.warp(blkTs);
        vm.roll(blocknum);
        // The correct contract requires 10 ether, buggy requires 1 ether.
        // We supply exactly 1 ether — it will succeed on buggy, fail (require msg.value) on correct.
        vm.deal(address(this), 1 ether);
        bool ok;
        try c.fallback{value: 1 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: for the correct contract, the second call must revert (ok == false).
        // The buggy contract accepts it, so ok will be true, breaking the rule.
        assertTrue(!ok);
    }
}

