pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // The admissible domain: any positive amount up to 100 ether, skipping multiples-of-15 blocks
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.roll(1); // block.number = 1, not a multiple of 15
        vm.warp(block.timestamp + 1);

        uint256 balanceBefore = address(c).balance;
        address sender = address(0x1234);
        vm.deal(sender, amount);
        vm.prank(sender);
        // For the reference, only amount == 10 ether succeeds; the bug requires amount == 1 ether
        // We let the fuzzer explore all amounts; if the call reverts, balance stays the same.
        // The property: after the call, balance == balanceBefore + (amount if call succeeded else 0).
        // The bug violates this because for amount == 10 ether the call reverts, yet the bug's require would
        // have accepted 1 ether, so the balance equality fails when fuzzer picks amount == 1 ether (bug
        // succeeds and increases balance, reference reverts and balance stays the same).
        (bool ok,) = address(c).call{value: amount}("");
        if (ok) {
            assertEq(address(c).balance, balanceBefore + amount);
        } else {
            assertEq(address(c).balance, balanceBefore);
        }
    }
}

