pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 priorTime, uint256 currentTime) public {
        vm.assume(priorTime >= 1 days);
        vm.assume(currentTime >= priorTime);
        vm.assume(currentTime <= priorTime + 1 days);
        vm.assume(address(c).balance == 0);
        vm.deal(address(this), 10 ether);
        // Warp to priorTime, send a successful fallback to set pastBlockTime to priorTime
        vm.warp(priorTime);
        c.f{value: 10 ether}();
        // Now warp to currentTime and attempt another fallback with value = 10 ether
        vm.warp(currentTime);
        vm.deal(address(this), 10 ether);
        bool ok;
        try c.f{value: 10 ether}() { ok = true; } catch { ok = false; }
        // If currentTime equals priorTime, the reference must revert and the mutant succeeds;
        // otherwise, the call succeeds in both.
        if (currentTime == priorTime) {
            assertTrue(ok == false);
        } else {
            assertTrue(ok == true);
        }
    }
}

