contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTs, uint256 pastTs) public {
        // admissible: pastTs < warpTs so the reference's require(block.timestamp > pastBlockTime) is satisfied
        vm.assume(pastTs < warpTs);

