        vm.warp(pastTs);

        // new call: reference must reject because block.timestamp == pastBlockTime;
        // mutant updated pastBlockTime first, so require passes
        vm.deal(address(this), 10 ether);
        bool success;
        try c.fallback{value: 10 ether}() { success = true; } catch { success = false; }
        // property: call must fail (reference) but mutant succeeds
        assertTrue(!success);
    }
}

